class MyInput(val list: List<String>) {
    var index = 0
    val max = list.size
    fun hasNext(): Boolean = index < max
    fun next(): String {
        if (hasNext()) {
            return list[index++]
        } else {
            throw RuntimeException("ArrayIndexOutOfBoundsException ‚There is no more input")
        }
    }
}

fun init(input: List<String>): MyInput = MyInput(input)
